"""Independent editor checks following public artifact recovery."""
import base64, hashlib, json, pathlib, sys
from PIL import Image
from playwright.sync_api import sync_playwright
out=pathlib.Path(sys.argv[1]);results={'checks':{},'issues':[],'limits':['No independent human playtest or listening test','No anti-agent effectiveness evaluation']}
def check(name,value,details=None):
    results['checks'][name]={'pass':bool(value),'details':details}
    if not value:results['issues'].append(name)
    print(name,value,details or '',flush=True)
base='http://host.docker.internal:18114/'
project=json.loads((out/'public/media/Final_Final_REAL.recovery.json').read_text())
solve=json.loads((out/'independent-solve.json').read_text());names=sorted(solve['rectangles']);best=solve['ranked'][1][1]
with sync_playwright() as p:
    browser=p.chromium.launch(executable_path='/usr/bin/chromium-browser',headless=True,args=['--no-sandbox'])
    page=browser.new_page(viewport={'width':1366,'height':768},device_scale_factor=1)
    errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
    page.goto(base);page.locator('#loading').wait_for(state='hidden')
    state=lambda:page.evaluate("JSON.parse(localStorage.getItem('sample-text-1-project'))")
    act=lambda a:page.locator(f'button[data-action="{a}"]:visible').first.click()
    def setfield(sel,val):page.locator(sel).fill(str(val));page.locator(sel).press('Tab')
    def shot(name):page.screenshot(path=str(out/name),full_page=True)
    page.locator('[data-source="sample_text"]').click()
    act('inspect');page.locator('#sample-x').fill('606');page.locator('#sample-y').fill('382')
    text=page.locator('#rgba-values').inner_text();expected=Image.open(out/'public/media/sample_text.png').getpixel((606,382))
    check('inspector_raw_pixel',list(map(int,text.replace('R','').replace('G','').replace('B','').replace('A','').split()))==list(expected),text)
    page.locator('#inspect-mode').select_option('none');shot('inspector-review-1366.png')
    with page.expect_download() as d:page.locator('#export-inspection').click()
    d.value.save_as(out/'inspector-export.png')
    check('inspector_export_raw_rgb',Image.open(out/'inspector-export.png').convert('RGB').tobytes()==Image.open(out/'public/media/sample_text.png').convert('RGB').tobytes())
    page.keyboard.press('Escape');check('dialog_focus_restored',page.evaluate("document.activeElement.dataset.action")=='inspect')
    for s in project['sources']:
        raw64=page.evaluate("""async url=>{let m=await import('./pixels.js');let b=await fetch(url).then(r=>r.arrayBuffer());let a=(await m.decodePNG(b)).rgba;let t='';for(let i=0;i<a.length;i+=16384)t+=String.fromCharCode(...a.subarray(i,i+16384));return btoa(t)}""",s['file'])
        got=hashlib.sha256(base64.b64decode(raw64)).hexdigest();want=hashlib.sha256(Image.open(out/'public'/s['file']).convert('RGBA').tobytes()).hexdigest()
        check('raw_decoder_'+s['id'],got==want,got)
    page.locator('[data-source="doritos"]').focus();page.keyboard.press('Enter')
    focused=page.evaluate("({tag:document.activeElement.tagName,source:document.activeElement.dataset.source||null})")
    check('media_selection_retains_keyboard_focus',focused['source']=='doritos',focused)
    for slot,v in enumerate(best):
        name=names[v//4];flip=v%4;s=next(s for s in project['sources'] if s['name']==name);e=next(e for e in project['events'] if e['source']==s['id'] and e['start']==16)
        page.locator('#event-source').select_option(e['id']);page.locator('#alpha-mode').select_option('none')
        act('crop');rect=solve['rectangles'][name]
        for k,val in zip(['x','y','w','h'],[rect[0],rect[1],rect[2]-rect[0],rect[3]-rect[1]]):page.locator('#crop-'+k).fill(str(val))
        page.locator('#apply-crop').click();page.locator('#flip-x').set_checked(bool(flip&1));page.locator('#flip-y').set_checked(bool(flip&2));act('native-size')
        setfield('#place-x',(slot%3)*384);setfield('#place-y',(slot//3)*324)
    actual=state();check('source_interpretation_shared',all(x=='none' for x in actual['alpha'].values()))
    check('earlier_event_geometry_preserved',all(e==next(x for x in project['events'] if x['id']==e['id']) for e in actual['events'] if e['start']<16))
    page.locator('#guides').click();shot('recovered-review-1366.png')
    with page.expect_download() as d:act('export')
    d.value.save_as(out/'browser-export.png')
    check('actual_export_equals_public_recovery',Image.open(out/'browser-export.png').convert('RGB').tobytes()==Image.open(out/'assembly-1.png').convert('RGB').tobytes())
    with page.expect_download() as d:act('save')
    d.value.save_as(out/'saved-project.json');saved=state()
    before=page.locator('#place-x').input_value();setfield('#place-x',int(before)+13);act('undo');check('undo_arbitrary_edit',page.locator('#place-x').input_value()==before)
    act('redo');check('redo_arbitrary_edit',page.locator('#place-x').input_value()==str(int(before)+13));act('undo')
    page.reload();page.locator('#loading').wait_for(state='hidden');check('reload_preserves_edits',state()==saved)
    page.locator('#project-file').set_input_files({'name':'incomplete.json','mimeType':'application/json','buffer':b'{"format":"montage-recovery-v1"}'})
    page.locator('#modal').wait_for(state='visible');check('malformed_import_preserves_edits',state()==saved,page.locator('#modal').inner_text());page.keyboard.press('Escape')
    act('crop');page.locator('#crop-w').fill('2000');page.locator('#apply-crop').click();check('invalid_crop_visible_error',page.locator('#crop-error').is_visible());page.keyboard.press('Escape');check('crop_cancel_preserves_edits',state()==saved)
    page.locator('#preview').focus();x=page.locator('#place-x').input_value();page.keyboard.press('Shift+ArrowRight');check('keyboard_nudge',page.locator('#place-x').input_value()==str(int(x)+10));page.keyboard.press('Control+z')
    page.locator('#solo').click();check('solo_enabled',page.locator('#solo').get_attribute('aria-pressed')=='true');page.locator('#solo').click()
    page.locator('#visible').uncheck();currentid=page.locator('#event-source').input_value();check('visibility_changes_state',not next(e for e in state()['events'] if e['id']==currentid)['visible']);act('undo')
    page.locator('[data-track-mute="1"]').click();check('track_mute_applies_occurrences',all(not e['visible'] for e in state()['events'] if e['track']==1));act('undo')
    page.locator('[data-menu="file-menu"]').click();act('reset');page.locator('#confirm-reset').click();check('reset_matches_original',state()==project);act('undo');check('reset_is_undoable',state()==saved)
    page.locator('#project-file').set_input_files(str(out/'saved-project.json'));check('saved_import_roundtrip',state()==saved)
    page.set_viewport_size({'width':1920,'height':1080});shot('recovered-review-1920.png')
    act('large-preview');shot('reward-review-1920.png');page.keyboard.press('Escape')
    page.evaluate("""()=>{window.qaAudioContext=new AudioContext();window.qaSource=qaAudioContext.createMediaElementSource(document.querySelector('#soundtrack'));window.qaAnalyser=qaAudioContext.createAnalyser();qaAnalyser.fftSize=2048;qaSource.connect(qaAnalyser);qaAnalyser.connect(qaAudioContext.destination)}""")
    act('start');page.locator('#play').click();page.evaluate('qaAudioContext.resume()')
    def rms():return page.evaluate("""async()=>{let a=new Float32Array(2048),sum=0,n=0;for(let j=0;j<25;j++){await new Promise(r=>setTimeout(r,25));qaAnalyser.getFloatTimeDomainData(a);for(let v of a){sum+=v*v;n++}}return Math.sqrt(sum/n)}""")
    level=rms();check('actual_audio_signal',level>0.00001,level)
    page.locator('#mute').click();page.wait_for_timeout(200);muted=rms();check('mute_silences_signal',muted<0.0000001,muted)
    page.locator('#mute').click();page.locator('#volume').fill('0');page.wait_for_timeout(200);zero=rms();check('zero_volume_silences_signal',zero<0.0000001,zero)
    page.locator('#volume').fill('20');low=rms();check('volume_restores_signal',low>0.00001,low)
    act('inspect');check('dialog_pauses_media',page.evaluate("document.querySelector('#soundtrack').paused && document.querySelector('#footage').paused"));page.keyboard.press('Escape')
    page.reload();page.locator('#loading').wait_for(state='hidden');check('volume_preference_persists',page.locator('#volume').input_value()=='20')
    check('no_browser_errors',not errors,errors);browser.close()
(out/'browser-review.json').write_text(json.dumps(results,indent=2));print(json.dumps(results,indent=2),flush=True)
